/**
 * The media types a generator hands the library (generated-sink.ts re-exports them). A leaf module, so a port
 * that reads generated bytes (Content Credentials) can name them without importing the sink and its provenance.
 * AGT2 sbx: videos too, for what the agent's workspace shell makes (workspace.importMedia).
 */
export const GENERATED_MEDIA_TYPES = [
  'audio/mpeg',
  'audio/wav',
  'audio/flac',
  'audio/ogg',
  'image/png',
  'image/jpeg',
  'image/webp',
  'video/mp4',
  'video/quicktime',
] as const;
export type GeneratedMediaType = (typeof GENERATED_MEDIA_TYPES)[number];
